     1→/**
     2→ * FreeLang Nexus - AST 노드 정의
     3→ * V 모드 함수와 Python 모드 함수 통합 AST
     4→ */
     5→
     6→/**
     7→ * 모든 AST 노드의 기본 인터페이스
     8→ */
     9→export interface ASTNode {
    10→  type: string;
    11→  line: number;
    12→  column: number;
    13→  mode: 'v' | 'python' | 'auto';
    14→}
    15→
    16→/**
    17→ * 파라미터 정의
    18→ */
    19→export interface Parameter {
    20→  name: string;
    21→  typeAnnotation?: string; // i64, string 등 (선택)
    22→  line: number;
    23→  column: number;
    24→}
    25→
    26→/**
    27→ * V 모드 함수
    28→ * 예: fn add(x: i64, y: i64) -> i64 { return x + y }
    29→ */
    30→export interface VFunction extends ASTNode {
    31→  type: 'VFunction';
    32→  name: string;
    33→  params: Parameter[];
    34→  returnType?: string; // -> 타입
    35→  body: Statement[];
    36→  mode: 'v';
    37→}
    38→
    39→/**
    40→ * Python 모드 함수
    41→ * 예: def add(a, b): return a + b
    42→ */
    43→export interface PyFunction extends ASTNode {
    44→  type: 'PyFunction';
    45→  name: string;
    46→  params: Parameter[];
    47→  returnType?: string; // -> 타입 (선택)
    48→  body: Statement[];
    49→  mode: 'python';
    50→}
    51→
    52→/**
    53→ * Return 문장
    54→ */
    55→export interface ReturnStatement extends ASTNode {
    56→  type: 'Return';
    57→  value?: Expression;
    58→}
    59→
    60→/**
    61→ * 할당 문장
    62→ */
    63→export interface AssignStatement extends ASTNode {
    64→  type: 'Assign';
    65→  name: string;
    66→  value: Expression;
    67→}
    68→
    69→/**
    70→ * 표현식 문장
    71→ */
    72→export interface ExprStatement extends ASTNode {
    73→  type: 'ExprStatement';
    74→  expression: Expression;
    75→}
    76→
    77→/**
    78→ * If 문장
    79→ */
    80→export interface IfStatement extends ASTNode {
    81→  type: 'IfStatement';
    82→  condition: Expression;
    83→  thenBranch: Statement[];
    84→  elseBranch?: Statement[];
    85→}
    86→
    87→/**
    88→ * While 루프
    89→ */
    90→export interface WhileStatement extends ASTNode {
    91→  type: 'WhileStatement';
    92→  condition: Expression;
    93→  body: Statement[];
    94→}
    95→
    96→/**
    97→ * For-In 루프
    98→ * for i in range(10) { body }
    99→ * for item in arr { body }
   100→ */
   101→export interface ForStatement extends ASTNode {
   102→  type: 'ForStatement';
   103→  variable: string;     // 루프 변수명
   104→  iterable: Expression; // range(10) CallExpr 또는 arr Identifier
   105→  body: Statement[];
   106→}
   107→
   108→/**
   109→ * 문장 타입 (Return, Assign, ExprStatement, IfStatement, WhileStatement, ForStatement)
   110→ */
   111→export type Statement = ReturnStatement | AssignStatement | ExprStatement | IfStatement | WhileStatement | ForStatement;
   112→
   113→/**
   114→ * 숫자 리터럴
   115→ */
   116→export interface NumberLiteral extends ASTNode {
   117→  type: 'Number';
   118→  value: number | string; // 16진수, 이진수 표현 가능
   119→}
   120→
   121→/**
   122→ * 문자열 리터럴
   123→ */
   124→export interface StringLiteral extends ASTNode {
   125→  type: 'String';
   126→  value: string;
   127→}
   128→
   129→/**
   130→ * 식별자 (변수명, 함수명 등)
   131→ */
   132→export interface Identifier extends ASTNode {
   133→  type: 'Identifier';
   134→  name: string;
   135→}
   136→
   137→/**
   138→ * 이항 연산식
   139→ * 예: x + y, a * b
   140→ */
   141→export interface BinaryExpr extends ASTNode {
   142→  type: 'BinaryExpr';
   143→  left: Expression;
   144→  operator: string; // +, -, *, /, &&, ||, ==, !=, <, >, <=, >=
   145→  right: Expression;
   146→}
   147→
   148→/**
   149→ * 함수 호출 표현식
   150→ * 예: foo(), Module::func()
   151→ */
   152→export interface CallExpr extends ASTNode {
   153→  type: 'Call';
   154→  callee: Expression | string; // Identifier 또는 Module::func 형식 문자열
   155→  args: Expression[];
   156→}
   157→
   158→/**
   159→ * 배열 리터럴
   160→ * 예: [1, 2, 3], []
   161→ */
   162→export interface ArrayLiteral extends ASTNode {
   163→  type: 'Array';
   164→  elements: Expression[];
   165→}
   166→
   167→/**
   168→ * 배열 접근
   169→ * 예: arr[0], items[i]
   170→ */
   171→export interface ArrayAccess extends ASTNode {
   172→  type: 'ArrayAccess';
   173→  object: Expression;
   174→  index: Expression;
   175→}
   176→
   177→/**
   178→ * 멤버 접근
   179→ * 예: arr.length, obj.property
   180→ */
   181→export interface MemberAccess extends ASTNode {
   182→  type: 'MemberAccess';
   183→  object: Expression;
   184→  property: string;
   185→}
   186→
   187→/**
