        property: propToken.value,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    } else {
      break;
    }
  }

  return expr;
}

/**
 * 기본 표현식 파싱 (리터럴, 식별자 등)
 */
private parsePrimary(): AST.Expression {
  const token = this.peek();

  // 숫자
  if (token.type === TokenType.NUMBER) {
    this.advance();
    return {
      type: 'Number',
      value: token.value,
      line: token.line,
      column: token.column,
      mode: token.mode,
    };
  }

  // 문자열
  if (token.type === TokenType.STRING) {
    this.advance();
    return {
      type: 'String',
      value: token.value,
      line: token.line,
      column: token.column,
      mode: token.mode,
    };
  }

  // true, false
  if (token.type === TokenType.TRUE || token.type === TokenType.FALSE) {
    this.advance();
    return {
      type: 'Number',
      value: token.type === TokenType.TRUE ? 1 : 0,
      line: token.line,
      column: token.column,
      mode: token.mode,
    };
  }

  // 배열 리터럴: [1, 2, 3]
  if (token.type === TokenType.LBRACKET) {
    return this.parseArrayLiteral();
  }

  // 식별자
  if (token.type === TokenType.IDENTIFIER) {
    this.advance();
    return {
      type: 'Identifier',
      name: token.value,
      line: token.line,
      column: token.column,
      mode: token.mode,
    };
  }

  // 괄호 식
  if (this.match(TokenType.LPAREN)) {
    const expr = this.parseExpression();
    this.consume(TokenType.RPAREN, ') 필요');
    return expr;
  }

  throw new Error(`예상치 못한 토큰: ${token.value} at line ${token.line}`);
}

/**
 * 배열 리터럴 파싱
 * [1, 2, 3], [], [a+b, c*d], [1, 2,] (trailing comma 지원)
 */
private parseArrayLiteral(): AST.ArrayLiteral {
  const startToken = this.consume(TokenType.LBRACKET, '[');
  const elements: AST.Expression[] = [];

  // 빈 배열 또는 요소들
  while (!this.check(TokenType.RBRACKET) && !this.isAtEnd()) {
    elements.push(this.parseExpression());

    // 쉼표가 있으면 계속, 없으면 종료
    if (!this.match(TokenType.COMMA)) {
      break;
    }

    // trailing comma: 쉼표 뒤에 ] 가 있으면 즉시 종료
    if (this.check(TokenType.RBRACKET)) {
      break;
    }
  }

