        return {
          type: 'Assign',
          name,
          value,
          line: startToken.line,
          column: startToken.column,
          mode: startToken.mode,
        };
      }

      // 아니면 전체 표현식으로 다시 파싱 (함수호출 등 포함)
      // pos를 한 칸 뒤로 이동하여 식별자부터 다시 파싱
      this.pos--;
      const expr = this.parseExpression();

      return {
        type: 'ExprStatement',
        expression: expr,
        line: startToken.line,
        column: startToken.column,
        mode: startToken.mode,
      };
    }

    throw new Error(`예상치 못한 토큰 at line ${startToken.line}`);
  }

  /**
   * If 문장 파싱
   * if condition { body } [else { body }]
   */
  private parseIfStatement(): AST.IfStatement {
    const startToken = this.consume(TokenType.IF, 'if 키워드 필요');
    const condition = this.parseExpression();
    this.consume(TokenType.LBRACE, '{ 필요');
    const thenBranch = this.parseVBlock();
    this.consume(TokenType.RBRACE, '} 필요');

    let elseBranch: AST.Statement[] | undefined;
    if (this.match(TokenType.ELSE)) {
      this.consume(TokenType.LBRACE, '{ 필요');
      elseBranch = this.parseVBlock();
      this.consume(TokenType.RBRACE, '} 필요');
    }

    return {
      type: 'IfStatement',
      condition,
      thenBranch,
      elseBranch,
      line: startToken.line,
      column: startToken.column,
      mode: startToken.mode,
    };
  }

  /**
   * While 루프 파싱
   * while condition { body }
   */
  private parseWhileStatement(): AST.WhileStatement {
    const startToken = this.consume(TokenType.WHILE, 'while 키워드 필요');
    const condition = this.parseExpression();
    this.consume(TokenType.LBRACE, '{ 필요');
    const body = this.parseVBlock();
    this.consume(TokenType.RBRACE, '} 필요');

    return {
      type: 'WhileStatement',
      condition,
      body,
      line: startToken.line,
      column: startToken.column,
      mode: startToken.mode,
    };
  }

  /**
   * For-In 루프 파싱
   * for <variable> in <iterable> { <body> }
   */
  private parseForStatement(): AST.ForStatement {
    const startToken = this.consume(TokenType.FOR, 'for 키워드 필요');
    const varToken = this.consume(TokenType.IDENTIFIER, '루프 변수명 필요');
    this.consume(TokenType.IN, 'in 키워드 필요');
    const iterable = this.parseExpression();
    this.consume(TokenType.LBRACE, '{ 필요');
    const body = this.parseVBlock();
    this.consume(TokenType.RBRACE, '} 필요');

    return {
      type: 'ForStatement',
      variable: varToken.value,
      iterable,
      body,
      line: startToken.line,
      column: startToken.column,
      mode: startToken.mode,
    };
  }

  /**
   * 표현식 파싱
   * 간단한 구현: 곱셈/나눗셈 → 덧셈/뺄셈 → 비교/논리
   */
  private parseExpression(): AST.Expression {
    return this.parseLogicalOr();
  }

  /**
   * 논리 OR 파싱: ||
   */
  private parseLogicalOr(): AST.Expression {
    let expr = this.parseLogicalAnd();

    while (this.match(TokenType.OR)) {
      const operator = this.previous().value;
      const right = this.parseLogicalAnd();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 논리 AND 파싱: &&
   */
  private parseLogicalAnd(): AST.Expression {
    let expr = this.parseEquality();

    while (this.match(TokenType.AND)) {
      const operator = this.previous().value;
      const right = this.parseEquality();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 등호/부등호 파싱: ==, !=
   */
  private parseEquality(): AST.Expression {
    let expr = this.parseComparison();

    while (this.match(TokenType.EQ, TokenType.NE)) {
      const operator = this.previous().value;
      const right = this.parseComparison();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 비교 파싱: <, >, <=, >=
   */
  private parseComparison(): AST.Expression {
    let expr = this.parseAddition();

    while (this.match(TokenType.LT, TokenType.GT, TokenType.LE, TokenType.GE)) {
      const operator = this.previous().value;
      const right = this.parseAddition();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 덧셈/뺄셈 파싱
   */
  private parseAddition(): AST.Expression {
    let expr = this.parseMultiplication();

    while (this.match(TokenType.PLUS, TokenType.MINUS)) {
      const operator = this.previous().value;
      const right = this.parseMultiplication();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 곱셈/나눗셈 파싱
   */
  private parseMultiplication(): AST.Expression {
    let expr = this.parseUnary();

    while (this.match(TokenType.STAR, TokenType.SLASH)) {
      const operator = this.previous().value;
      const right = this.parseUnary();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 단항 연산 파싱
   */
  private parseUnary(): AST.Expression {
    // TODO: 단항 연산자 (-, !, ~) 처리 가능
    return this.parsePostfix();
  }

  /**
   * 후위 연산 파싱 (함수 호출, 배열 접근)
   */
  private parsePostfix(): AST.Expression {
    let expr = this.parsePrimary();

    while (true) {
      // 함수 호출: foo()
      if (this.match(TokenType.LPAREN)) {
        const args = this.parseArguments();
        this.consume(TokenType.RPAREN, ') 필요');

        const token = this.previous();
        expr = {
          type: 'Call',
          callee: expr,
          args,
          line: token.line,
          column: token.column,
          mode: token.mode,
        };
      }
      // 배열 인덱싱: arr[0]
      else if (this.match(TokenType.LBRACKET)) {
        const index = this.parseExpression();
        const token = this.consume(TokenType.RBRACKET, '] 필요');

        expr = {
          type: 'ArrayAccess',
          object: expr,
          index,
          line: token.line,
          column: token.column,
          mode: token.mode,
        };
      }
      // 멤버 접근: obj.property
      else if (this.match(TokenType.DOT)) {
        const propToken = this.consume(TokenType.IDENTIFIER, '프로퍼티명 필요');
        const token = this.previous();

        expr = {
          type: 'MemberAccess',
          object: expr,
          property: propToken.value,
          line: token.line,
          column: token.column,
          mode: token.mode,
        };
      } else {
        break;
      }
    }

    return expr;
  }

  /**
   * 기본 표현식 파싱 (리터럴, 식별자 등)
   */
  private parsePrimary(): AST.Expression {
    const token = this.peek();

    // 숫자
    if (token.type === TokenType.NUMBER) {
      this.advance();
      return {
        type: 'Number',
        value: token.value,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    // 문자열
    if (token.type === TokenType.STRING) {
      this.advance();
      return {
        type: 'String',
        value: token.value,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    // true, false
    if (token.type === TokenType.TRUE || token.type === TokenType.FALSE) {
      this.advance();
      return {
        type: 'Number',
        value: token.type === TokenType.TRUE ? 1 : 0,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    // 배열 리터럴: [1, 2, 3]
    if (token.type === TokenType.LBRACKET) {
      return this.parseArrayLiteral();
    }

    // 식별자
    if (token.type === TokenType.IDENTIFIER) {
      this.advance();
      return {
        type: 'Identifier',
        name: token.value,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    // 괄호 식
    if (this.match(TokenType.LPAREN)) {
      const expr = this.parseExpression();
      this.consume(TokenType.RPAREN, ') 필요');
      return expr;
    }

    throw new Error(`예상치 못한 토큰: ${token.value} at line ${token.line}`);
  }

  /**
   * 배열 리터럴 파싱
   * [1, 2, 3], [], [a+b, c*d], [1, 2,] (trailing comma 지원)
   */
  private parseArrayLiteral(): AST.ArrayLiteral {
    const startToken = this.consume(TokenType.LBRACKET, '[');
    const elements: AST.Expression[] = [];

    // 빈 배열 또는 요소들
    while (!this.check(TokenType.RBRACKET) && !this.isAtEnd()) {
      elements.push(this.parseExpression());

      // 쉼표가 있으면 계속, 없으면 종료
      if (!this.match(TokenType.COMMA)) {
        break;
      }

      // trailing comma: 쉼표 뒤에 ] 가 있으면 즉시 종료
      if (this.check(TokenType.RBRACKET)) {
        break;
      }
    }

    const endToken = this.consume(TokenType.RBRACKET, '] 필요');

    return {
      type: 'Array',
      elements,
      line: startToken.line,
      column: startToken.column,
      mode: startToken.mode,
    };
  }

  /**
   * 함수 호출 인자 파싱
   */
  private parseArguments(): AST.Expression[] {
    const args: AST.Expression[] = [];

    if (!this.check(TokenType.RPAREN)) {
      do {
        args.push(this.parseExpression());
      } while (this.match(TokenType.COMMA));
    }

    return args;
  }

  // ========== 헬퍼 메서드 ==========

  private peek(): Token {
    if (this.pos >= this.tokens.length) {
      return this.tokens[this.tokens.length - 1]; // EOF 토큰
    }
    return this.tokens[this.pos];
  }

  private advance(): Token {
    if (!this.isAtEnd()) {
      this.pos++;
    }
    return this.previous();
  }

  private previous(): Token {
    return this.tokens[this.pos - 1];
  }

  private isAtEnd(): boolean {
    return this.peek().type === TokenType.EOF;
  }

  private check(type: TokenType): boolean {
    if (this.isAtEnd()) return false;
    return this.peek().type === type;
  }

  private match(...types: TokenType[]): boolean {
    for (const type of types) {
      if (this.check(type)) {
        this.advance();
        return true;
      }
    }
    return false;
  }

  private consume(type: TokenType, message: string): Token {
    if (this.check(type)) return this.advance();

    const token = this.peek();
    throw new Error(`${message} at line ${token.line}, got ${token.value}`);
  }

  private skipNewlines(): void {
    while (this.match(TokenType.NEWLINE)) {
      // 계속
    }
  }
}

