/**
 * FreeLang Nexus - Phase N.4 테스트
 * 구조체 정의, 초기화, 필드 접근
 */

import { NexusLexer } from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';
import * as AST from '../src/nexus/parser/ast';

describe('Phase N.4: 구조체 (Struct)', () => {
  describe('파서: 구조체 정의', () => {
    it('1. StructDef AST 파싱 - 구조체 이름 확인', () => {
      const code = `struct Person {
        name: string
        age: i64
      }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();

      expect(program.body.length).toBe(1);
      const structDef = program.body[0] as AST.StructDef;
      expect(structDef.type).toBe('StructDef');
      expect(structDef.name).toBe('Person');
    });

    it('2. StructDef 필드 파싱 - 필드명 + 타입 (2개 필드)', () => {
      const code = `struct Person {
        name: string
        age: i64
      }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();

      const structDef = program.body[0] as AST.StructDef;
      expect(structDef.fields.length).toBe(2);

      expect(structDef.fields[0].name).toBe('name');
      expect(structDef.fields[0].typeAnnotation).toBe('string');

      expect(structDef.fields[1].name).toBe('age');
      expect(structDef.fields[1].typeAnnotation).toBe('i64');
    });

    it('3. StructLiteral 파싱 - 초기화 표현식', () => {
      const code = `fn test() {
        let p = Person { name: "Alice", age: 30 }
      }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();

      const vfn = program.body[0] as AST.VFunction;
      const assignStmt = vfn.body[0] as AST.AssignStatement;
      const structLit = assignStmt.value as AST.StructLiteral;

      expect(structLit.type).toBe('StructLiteral');
      expect(structLit.name).toBe('Person');
      expect(Object.keys(structLit.fields).length).toBe(2);
      expect((structLit.fields.name as AST.StringLiteral).value).toBe('"Alice"');
      expect((structLit.fields.age as AST.NumberLiteral).value).toBe(30);
    });
  });

  describe('코드젠: V 모드 (C)', () => {
    it('4. V 모드 → typedef struct { ... } 생성', () => {
      const code = `struct Person {
        name: string
        age: i64
      }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();
      const codegen = new NexusCodegen();
      const result = codegen.generate(program);

      expect(result.c).toContain('typedef struct {');
      expect(result.c).toContain('char* name;');
      expect(result.c).toContain('long long age;');
      expect(result.c).toContain('} Person;');
    });

    it('5. V 모드 → 구조체 초기화 (Person){.name = "Alice", .age = 30} 생성', () => {
      const code = `struct Person {
        name: string
        age: i64
      }

      fn main() {
        let p = Person { name: "Alice", age: 30 }
      }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();
      const codegen = new NexusCodegen();
      const result = codegen.generate(program);

      expect(result.c).toContain('(Person){.name = "Alice", .age = 30}');
    });

    it('6. 멤버 접근 p.name → C p.name (기존 MemberAccess 재사용)', () => {
      const code = `fn test() {
        let p = Person { name: "Alice", age: 30 }
        println(p.name)
      }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();
      const codegen = new NexusCodegen();
      const result = codegen.generate(program);

      expect(result.c).toContain('p.name');
    });
  });

  describe('코드젠: Python 모드', () => {
    it('7. Python 모드 → class Person: ... 생성', () => {
      const code = `struct Person {
        name: string
        age: i64
      }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();
      const codegen = new NexusCodegen();
      const result = codegen.generate(program);

      expect(result.python).toContain('class Person:');
      expect(result.python).toContain('def __init__(self, name, age):');
      expect(result.python).toContain('self.name = name');
      expect(result.python).toContain('self.age = age');
    });

    it('8. Python 모드 → Person(name="Alice", age=30) 생성', () => {
      const code = `struct Person {
        name: string
        age: i64
      }

      def main():
        p = Person { name: "Alice", age: 30 }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();
      const codegen = new NexusCodegen();
      const result = codegen.generate(program);

      expect(result.python).toContain('Person(name="Alice", age=30)');
    });
  });

  describe('회귀 테스트', () => {
    it('기존 83개 테스트 영향 없음 - 일반 함수 파싱', () => {
      const code = `fn add(x: i64, y: i64) -> i64 {
        return x + y
      }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();

      expect(program.body.length).toBe(1);
      const vfn = program.body[0] as AST.VFunction;
      expect(vfn.type).toBe('VFunction');
      expect(vfn.name).toBe('add');
    });

    it('기존 83개 테스트 영향 없음 - 배열 초기화', () => {
      const code = `fn test() {
        let arr = [1, 2, 3]
      }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();

      const vfn = program.body[0] as AST.VFunction;
      const assignStmt = vfn.body[0] as AST.AssignStatement;
      const arrayLit = assignStmt.value as AST.ArrayLiteral;

      expect(arrayLit.type).toBe('Array');
      expect(arrayLit.elements.length).toBe(3);
    });
  });
});

