      const program = parser.parse();
      const codegen = new NexusCodegen();
      const result = codegen.generate(program);

      expect(result.c).toContain('p.name');
    });
  });

  describe('코드젠: Python 모드', () => {
    it('7. Python 모드 → class Person: ... 생성', () => {
      const code = `struct Person {
        name: string
        age: i64
      }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();
      const codegen = new NexusCodegen();
      const result = codegen.generate(program);

      expect(result.python).toContain('class Person:');
      expect(result.python).toContain('def __init__(self, name, age):');
      expect(result.python).toContain('self.name = name');
      expect(result.python).toContain('self.age = age');
    });

    it('8. Python 모드 → Person(name="Alice", age=30) 생성', () => {
      const code = `struct Person {
        name: string
        age: i64
      }

      def main():
        p = Person { name: "Alice", age: 30 }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();
      const codegen = new NexusCodegen();
      const result = codegen.generate(program);

      expect(result.python).toContain('Person(name="Alice", age=30)');
    });
  });

  describe('회귀 테스트', () => {
    it('기존 83개 테스트 영향 없음 - 일반 함수 파싱', () => {
      const code = `fn add(x: i64, y: i64) -> i64 {
        return x + y
      }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();

      expect(program.body.length).toBe(1);
      const vfn = program.body[0] as AST.VFunction;
      expect(vfn.type).toBe('VFunction');
      expect(vfn.name).toBe('add');
    });

    it('기존 83개 테스트 영향 없음 - 배열 초기화', () => {
      const code = `fn test() {
        let arr = [1, 2, 3]
      }`;

      const lexer = new NexusLexer(code, 'v');
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();

      const vfn = program.body[0] as AST.VFunction;
      const assignStmt = vfn.body[0] as AST.AssignStatement;
      const arrayLit = assignStmt.value as AST.ArrayLiteral;

      expect(arrayLit.type).toBe('Array');
      expect(arrayLit.elements.length).toBe(3);
    });
  });
});

