        name: string
        age: i64
      }`;

      const lexer = new NexusLexer(code);
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();

      const structDef = program.body[0] as AST.StructDef;
      expect(structDef.fields.length).toBe(2);

      expect(structDef.fields[0].name).toBe('name');
      expect(structDef.fields[0].typeAnnotation).toBe('string');

      expect(structDef.fields[1].name).toBe('age');
      expect(structDef.fields[1].typeAnnotation).toBe('i64');
    });

    it('3. StructLiteral 파싱 - 초기화 표현식', () => {
      const code = `fn test() {
        let p = Person { name: "Alice", age: 30 }
      }`;

      const lexer = new NexusLexer(code);
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();

      const vfn = program.body[0] as AST.VFunction;
      const assignStmt = vfn.body[0] as AST.AssignStatement;
      const structLit = assignStmt.value as AST.StructLiteral;

      expect(structLit.type).toBe('StructLiteral');
      expect(structLit.name).toBe('Person');
      expect(Object.keys(structLit.fields).length).toBe(2);
      expect((structLit.fields.name as AST.StringLiteral).value).toBe('"Alice"');
      expect(parseInt((structLit.fields.age as AST.NumberLiteral).value.toString())).toBe(30);
    });
  });

  describe('코드젠: V 모드 (C)', () => {
    it('4. V 모드 → typedef struct { ... } 생성', () => {
      const code = `struct Person {
        name: string
        age: i64
      }`;

      const lexer = new NexusLexer(code);
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();
      const codegen = new NexusCodegen();
      const result = codegen.generate(program);

      expect(result.c).toContain('typedef struct {');
      expect(result.c).toContain('char* name;');
      expect(result.c).toContain('long long age;');
      expect(result.c).toContain('} Person;');
    });

    it('5. V 모드 → 구조체 초기화 (Person){.name = "Alice", .age = 30} 생성', () => {
      const code = `struct Person {
        name: string
        age: i64
      }

      fn main() {
        let p = Person { name: "Alice", age: 30 }
      }`;

      const lexer = new NexusLexer(code);
      const tokens = lexer.tokenize();
      const parser = new NexusParser(tokens);
      const program = parser.parse();
      const codegen = new NexusCodegen();
      const result = codegen.generate(program);

      expect(result.c).toContain('(Person){.name = "Alice", .age = 30}');
    });

    it('6. 멤버 접근 p.name → C p.name (기존 MemberAccess 재사용)', () => {
      const code = `fn test() {
